<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\TemporalKeysGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\TemporalAuthCode;

class InMemoryTemporalKeys implements TemporalKeysGateway
{
    private readonly string $key;
    /** @var array<string, TemporalAuthCode> */
    private array $codes = [];

    public function __construct()
    {
        $this->key = bin2hex(random_bytes(16));
    }

    public function currentKey(): string
    {
        return $this->key;
    }

    public function encrypt(string $token): ?string
    {
        $iv = random_bytes(16);
        $cipher = openssl_encrypt($token, 'AES-256-CBC', $this->key, 0, $iv);
        if ($cipher === false) {
            return null;
        }
        return base64_encode($iv . $cipher);
    }

    public function verifyCypher(string $token): ?string
    {
        $raw = base64_decode($token, true);
        if ($raw === false || strlen($raw) < 17) {
            return null;
        }
        $iv = substr($raw, 0, 16);
        $cipher = substr($raw, 16);
        $plain = openssl_decrypt($cipher, 'AES-256-CBC', $this->key, 0, $iv);
        return $plain !== false ? $plain : null;
    }

    public function verifyToken(string $token): ?string
    {
        [$data, $sig] = array_pad(explode('.', $token, 2), 2, '');
        $expected = hash_hmac('sha256', $data, $this->key);
        if (!hash_equals($expected, $sig)) {
            return null;
        }
        return base64_decode($data) ?: null;
    }

    public function registerTemporalAuthCode(TemporalAuthCode $code): string
    {
        $codeKey = bin2hex(random_bytes(32));
        $this->codes[$codeKey] = $code;
        return $codeKey;
    }

    public function retrieveTemporalAuthCode(string $code): ?TemporalAuthCode
    {
        $entry = $this->codes[$code] ?? null;
        if ($entry !== null) {
            unset($this->codes[$code]);
        }
        return $entry;
    }
}
